can-make-arithmetic-progression-from-seq:
class Solution:
    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:
        arr.sort()
        d = arr[1] - arr[0]
        return all(arr[i] - arr[i - 1] == d for i in range(1, len(arr)))

categorize-box-according-to-criteria:
class Solution:
    def categorizeBox(self, length: int, width: int, height: int, mass: int) -> str:
        bulky = length * width * height >= 10 ** 9 or max(length, width, height) >= 10 ** 4
        heavy = mass >= 100
        if bulky and heavy:
            return 'Both'
        if bulky:
            return 'Bulky'
        if heavy:
            return 'Heavy'
        return 'Neither'

